listData:
{{(() => {
     const en = appsmith.store.bo_lang === 'en';
     const history = GetTrackingHistory.data || [];
     const orderData = GetOrderTracking.data[0] || {};
     const at = (x) => moment(x).format('DD.MM HH:mm');
     // Fleetbase writes its tracking statuses in English; the ones a merchant meets are put
     // into Bulgarian here, anything else stays as Fleetbase wrote it (2026-10-02).
     const bg = { 'Order Created': 'Поръчката е създадена', 'Order created': 'Поръчката е създадена', 'Order Dispatched': 'Възложена на шофьор',
       'Order dispatched': 'Възложена на шофьор', 'Driver Assigned': 'Възложена на шофьор', 'Driver assigned': 'Възложена на шофьор',
       'Order Started': 'В път', 'Started': 'В път', 'In Transit': 'В път', 'Enroute': 'В път', 'Order Completed': 'Доставена',
       'Completed': 'Доставена', 'Delivered': 'Доставена', 'Order canceled': 'Отказана', 'Order Canceled': 'Отказана', 'Canceled': 'Отказана',
       'Order Returned': 'Върната', 'Delivery attempted': 'Неуспешен опит', 'Returning': 'Връща се' };
     const tr = (s) => (en ? s : (bg[s] || s));
     if (history.length > 0) {
       return history.map(event => ({
         status: tr(event.status),
         details: en ? event.details : (bg[event.details] || event.details),
         date: at(event.created_at),
         completed: event.complete,
         icon: event.complete ? "✅" : "⭕"
       }));
     }
     const timeline = [];
     timeline.push({ status: en ? "Order created" : "Поръчката е създадена", details: en ? "Order has been placed" : "Поръчката е приета", date: at(orderData.created_at), completed: true, icon: "✅" });
     if (orderData.dispatched_at) {
       timeline.push({ status: en ? "Dispatched" : "Възложена на шофьор", details: en ? "Driver assigned" : "Има шофьор", date: at(orderData.dispatched_at), completed: true, icon: "✅" });
     }
     if (orderData.started_at) {
       timeline.push({ status: en ? "In transit" : "В път", details: en ? "On the way" : "Пратката пътува", date: at(orderData.started_at), completed: true, icon: "✅" });
     }
     if (orderData.order_status !== 'delivered') {
       timeline.push({ status: en ? "Delivery" : "Доставка", details: en ? "Estimated delivery" : "Очаквана доставка", date: orderData.scheduled_at ? at(orderData.scheduled_at) : (en ? "Today" : "Днес"), completed: false, icon: "⭕" });
     }
     return timeline;
   })()}}
